import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix, smoothstep, color, fract, sin, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, SRGBColorSpace } = ctx.THREE;

  const group = new Group();
  group.userData.handlers = {};

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Engineered gradient backdrop with subtle grain
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });

  const inkNode = color(colors.ink);
  const surfaceNode = color(colors.surface);
  const gradT = smoothstep(0.0, 1.0, uv().y);
  const gradient = mix(inkNode, surfaceNode, gradT);
  const grain = fract(
    sin(uv().x.mul(1534.0).add(uv().y.mul(7231.0))).mul(43758.5453)
  ).mul(0.03);

  backdropMat.colorNode = gradient.add(grain);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Atlas sprite
  const region = config.atlasRegion ?? { sourceRect: [0, 0, 512, 320] };
  const rect = region.sourceRect ?? [0, 0, 512, 320];
  let rx, ry, rw, rh;
  if (Array.isArray(rect)) {
    [rx, ry, rw, rh] = rect;
  } else {
    rx = rect.x ?? 0;
    ry = rect.y ?? 0;
    rw = rect.w ?? rect.width ?? 512;
    rh = rect.h ?? rect.height ?? 320;
  }

  const aspect = rw / rh || 1;
  const spriteW = 3.0;
  const spriteH = spriteW / aspect;

  const spriteGeo = new PlaneGeometry(spriteW, spriteH, 1, 1);
  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    alphaTest: 0.01,
    side: DoubleSide,
    depthWrite: true,
  });

  const sprite = new Mesh(spriteGeo, spriteMat);
  sprite.renderOrder = 1;
  group.add(sprite);

  let loadedTex = null;

  sprite.onBeforeRender = (renderer, scene, camera) => {
    sprite.lookAt(camera.position);
  };

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTex = tex;
        tex.colorSpace = SRGBColorSpace;
        tex.needsUpdate = true;

        const atlasW = tex.image?.width || rw;
        const atlasH = tex.image?.height || rh;

        const scaleX = rw / atlasW;
        const scaleY = rh / atlasH;
        const offsetX = rx / atlasW;
        const offsetY = ry / atlasH;

        const uvNode = uv()
          .mul(vec2(scaleX, scaleY))
          .add(vec2(offsetX, offsetY));

        spriteMat.map = texture(tex, uvNode);
        spriteMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  group.userData.cleanup = () => {
    sprite.onBeforeRender = null;

    if (loadedTex) {
      loadedTex.dispose();
      loadedTex = null;
    }

    spriteMat.dispose?.();
    backdropMat.dispose?.();
    spriteGeo.dispose();
    backdropGeo.dispose();
  };

  return group;
}
